  "implementation": "def solve(case):
    token_count = case['token_count']
    token_labels = [0] * token_count
    word_indices = case['word_token_indices']
    word_labels = case['word_labels']
    for i, indices in enumerate(word_indices):
        label = word_labels[i]
        for idx in indices:
            token_labels[idx] = label
    return {'token_labels': token_labels}"
